const fs=require('fs'),p=require('path'),c=require('crypto'),b=process.argv[2],rd=n=>JSON.parse(fs.readFileSync(p.join(b,n),'utf8'));const dom=fs.readFileSync(p.join(b,'Plan_audit_P01.html'),'utf8');const hrefs=[...dom.matchAll(/href=['"]([^'"]+)['"]/g)].map(m=>m[1]);const hids=[...dom.matchAll(/\bid=['"]([^'"]+)['"]/g)].map(m=>m[1]);console.log('HTML',dom.length,'links',hrefs.length,'ids',hids.length,'dup',hids.length-new Set(hids).size,'broken',hrefs.filter(x=>x.startsWith('#')?!hids.includes(x.slice(1)):!x.includes('://')&&!fs.existsSync(p.join(b,x.split('#')[0]))).slice(0,20));for (const z of rd('Plan_director.json').zones){let d=rd(z.file),a=d.controls||d.controale||d.checklists;console.log(z.id,z.name);console.log(a.map(x=>x.title||x.titlu||x.objective||x.requirement).join(' | ').slice(0,2700))};
const index=rd('Index_trasabilitate.json'),ps=new Map(index.pipelines.map(x=>[x.id,x])),cs=new Map(index.controls.map(x=>[x.id,x]));let inconsistent=[];for(let pi of ps.values()){for(const cc of pi.resolved_control_ids||[]){if(!cs.get(cc)?.planned_pipelines.includes(pi.id))inconsistent.push([pi.id,cc])}}for(let cc of cs.values())for(let pi of cc.planned_pipelines){if(!ps.get(pi)?.resolved_control_ids?.includes(cc.id))inconsistent.push([cc.id,pi])}console.log('Reciprocity remaining',inconsistent.length,inconsistent.slice(0,10));
